// What `async fn fetch() -> usize { read_some().await }`
// roughly compiles to (simplified; ReadFut assumed Unpin)
enum Fetch { Start, Waiting(ReadFut), Done }

impl Future for Fetch {
    type Output = usize;
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>)
        -> Poll<usize> {
        loop {
            match &mut *self {
                Fetch::Start => {
                    let fut = read_some(); // child future, inert
                    *self = Fetch::Waiting(fut);
                }
                Fetch::Waiting(fut) => match Pin::new(fut).poll(cx) {
                    Poll::Pending => return Poll::Pending,
                    Poll::Ready(n) => {
                        *self = Fetch::Done;
                        return Poll::Ready(n);
                    }
                },
                Fetch::Done => panic!("polled after completion"),
            }
        }
    }
}

use std::future::Future;
use std::pin::pin;
use std::task::{Context, Poll, Waker};

// The smallest possible executor: poll one future with a waker
// that does nothing. Fine for futures that wake themselves
// immediately; a real runtime parks the thread until woken.
fn block_on<F: Future>(f: F) -> F::Output {
    let mut f = pin!(f);
    let mut cx = Context::from_waker(Waker::noop());
    loop {
        if let Poll::Ready(v) = f.as_mut().poll(&mut cx) {
            return v;
        }
        std::thread::yield_now(); // a real executor would sleep here
    }
}

use tokio::task;

async fn handle(path: std::path::PathBuf) -> std::io::Result<u64> {
    // Bad: blocks this worker thread for the whole hash.
    // let digest = hash_file_sync(&path)?;

    // Good: move the blocking work to the blocking pool and await it.
    let digest = task::spawn_blocking(move || hash_file_sync(&path))
        .await
        .expect("blocking task panicked")?;
    Ok(digest)
}
